// Auto-remove applicants whose interview date has passed (the interview is "done").
// Self-contained: queries + deletes via the Supabase service key (Audit_Logs and
// Job_Requirements are RLS-blocked for the anon key). Children before parents for
// FK safety; every request guarded so one bad row can't halt the run.
const SB = 'https://kzszvpmwvvtfvcgdzgnj.supabase.co';
const KEY = $env.SUPABASE_SERVICE_KEY;
const H  = { apikey: KEY, Authorization: `Bearer ${KEY}` };
const HJ = { ...H, 'Content-Type': 'application/json', Prefer: 'return=minimal' };
function uuidv4(){return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return (c==='x'?r:(r&0x3|0x8)).toString(16);});}
const get  = async (url) => { try { return await this.helpers.httpRequest({ method:'GET', url, headers: H, json: true }); } catch (e) { return null; } };
const send = async (method, url, body) => { try { await this.helpers.httpRequest({ method, url, headers: HJ, body, json: true }); } catch (e) {} };

// An interview more than 12h in the past has already happened.
const cutoff = new Date(Date.now() - 12 * 60 * 60 * 1000).toISOString();
const interviews = (await get(`${SB}/rest/v1/Interviews?select=interview_id,evaluation_id&interview_date=lt.${cutoff}`)) || [];

let removed = 0;
for (const iv of interviews) {
  const evaluation_id = iv.evaluation_id;
  if (!evaluation_id) continue;

  // Resolve resume -> applicant and requirement -> company (for the audit entry).
  const evs = (await get(`${SB}/rest/v1/Evaluations?select=resume_id,requirement_id&evaluation_id=eq.${evaluation_id}`)) || [];
  const ev = evs[0] || {};
  const resume_id = ev.resume_id || null;
  const requirement_id = ev.requirement_id || null;
  let applicant_id = null, name = 'An applicant', company_id = null;
  if (resume_id) {
    const rs = (await get(`${SB}/rest/v1/Resumes?select=applicant_id&resume_id=eq.${resume_id}`)) || [];
    applicant_id = rs[0] ? rs[0].applicant_id : null;
  }
  if (applicant_id) {
    const ap = (await get(`${SB}/rest/v1/Applicants?select=full_name&applicant_id=eq.${applicant_id}`)) || [];
    if (ap[0] && ap[0].full_name) name = ap[0].full_name;
  }
  if (requirement_id) {
    const rq = (await get(`${SB}/rest/v1/Job_Requirements?select=company_id&requirement_id=eq.${requirement_id}`)) || [];
    company_id = rq[0] ? rq[0].company_id : null;
  }

  // Permanent audit (applicant_id=null so it survives the delete). Shows in the
  // company's bell Activity tab via the [c:<company_id>] scoping marker.
  if (company_id) {
    await send('POST', `${SB}/rest/v1/Audit_Logs`, {
      audit_log_id: uuidv4(),
      applicant_id: null,
      requirement_id: requirement_id || null,
      action_type: 'INTERVIEW_COMPLETED',
      action_details: `[c:${company_id}] ${name}'s interview date has passed; their application data was removed.`,
    });
  }

  // Detach any other audit rows referencing this applicant, then delete children -> parents.
  if (applicant_id) await send('PATCH',  `${SB}/rest/v1/Audit_Logs?applicant_id=eq.${applicant_id}`, { applicant_id: null });
  await send('DELETE', `${SB}/rest/v1/Interviews?evaluation_id=eq.${evaluation_id}`);
  if (applicant_id) await send('DELETE', `${SB}/rest/v1/Email_Logs?applicant_id=eq.${applicant_id}`);
  await send('DELETE', `${SB}/rest/v1/Evaluation_Pros?evaluation_id=eq.${evaluation_id}`);
  await send('DELETE', `${SB}/rest/v1/Evaluation_Cons?evaluation_id=eq.${evaluation_id}`);
  await send('DELETE', `${SB}/rest/v1/Evaluations?evaluation_id=eq.${evaluation_id}`);
  if (applicant_id) await send('DELETE', `${SB}/rest/v1/Resumes?applicant_id=eq.${applicant_id}`);
  if (applicant_id) await send('DELETE', `${SB}/rest/v1/Applicants?applicant_id=eq.${applicant_id}`);
  removed++;
}
return [{ json: { checked: interviews.length, removed } }];
